await prisma.$transaction(async (tx) => {
  const sender = await tx.user.update({
    where: { id: senderId },
    data: { credits: { decrement: amount } }
  });

  const receiver = await tx.user.update({
    where: { id: receiverId },
    data: { credits: { increment: amount } }
  });

  return { sender, receiver };
});
